<template>
  <main class="lesson">
    <header class="top"><div class="brand"><span class="brand-mark"><BookOpenCheck :size="21" /></span><span><strong>Inquiry Studio</strong><small>教案分析工作台</small></span></div><div class="top-context"><span>教案分析</span></div><div class="actions"><span class="save-state" role="status">{{ saving ? '正在保存修改…' : dirty ? '有未保存的修改' : document ? '已保存到服务器' : '新建教案' }}</span><button :disabled="busy" @click="leave('home')">返回首页</button><button :disabled="busy" @click="leave('dialogue')">返回对话模式</button><button v-if="document" :disabled="busy" @click="showVersions">历史版本</button><button v-if="document" :disabled="busy || !dirty" @click="save()">保存</button><button v-if="document" class="primary" :disabled="busy || dirty" @click="exportWord"><Download :size="15" /> 导出 Word</button></div></header>
    <p v-if="error" class="alert" role="alert">{{ error }}</p>
    <div class="workspace markdown-workspace" :class="{'show-side': mobileSide, 'outline-collapsed': outlineCollapsed || !document, 'assistant-collapsed': assistantCollapsed}">
      <nav v-if="document && !outlineCollapsed" class="outline" aria-label="教案目录"><div class="outline-head"><strong>教案目录</strong><span class="count">{{ outlineItems.length }}</span></div><p class="outline-title">{{ content!.title }}</p><button v-for="item in outlineItems" :key="item.offset" :class="{active: activeOutline === item.offset}" @click="jumpToOutline(item.offset)"><FileText :size="15" /> <span>{{ item.title }}</span></button><p v-if="!outlineItems.length" class="muted">暂无识别出的章节标题。可在正文中使用 Markdown 标题。</p></nav>
      <section v-if="document" class="editor markdown-editor"><div class="toolbar"><button class="panel-toggle" :aria-label="outlineCollapsed ? '展开目录' : '收起目录'" @click="outlineCollapsed = !outlineCollapsed"><PanelLeft :size="17" /></button><select v-if="outlineItems.length" class="compact-outline" aria-label="章节目录" :value="activeOutline" @change="jumpToOutline(Number(($event.target as HTMLSelectElement).value))"><option :value="-1" disabled>章节目录</option><option v-for="item in outlineItems" :key="item.offset" :value="item.offset">{{ item.title }}</option></select><strong>教案全文</strong><span class="version-badge">Markdown · 版本 {{ document.version }}</span><button v-if="lastApplied" :disabled="markdown !== lastApplied.after || busy" @click="undoSuggestion">撤销本次采纳</button><button class="mobile" @click="mobileSide = true">打开教学助手</button><button class="assistant-toggle" :aria-label="assistantCollapsed ? '展开助手' : '收起助手'" @click="assistantCollapsed = !assistantCollapsed"><PanelRight :size="17" /></button></div><p class="editor-hint">直接编辑全文；选中一段后可在右侧请求优化。采纳建议后自动保存，手动编辑后请保存。</p><textarea ref="markdownEditor" v-model="markdown" class="markdown-input" :disabled="busy || document.locked" aria-label="教案 Markdown 全文" spellcheck="false" @select="captureSelection" @input="clearSelection" ></textarea></section>
      <section v-else class="editor markdown-editor empty-editor"><div class="toolbar"><strong>教案全文</strong><span class="version-badge">等待导入</span><button class="mobile" @click="mobileSide = true">打开教学助手</button><button class="assistant-toggle" :aria-label="assistantCollapsed ? '展开助手' : '收起助手'" @click="assistantCollapsed = !assistantCollapsed"><PanelRight :size="17" /></button></div><div class="empty-document" :class="{'is-dragging': dragging}" @dragover.prevent="dragging = !busy" @dragleave.prevent="dragging = false" @drop.prevent="dropFile"><span class="empty-icon"><FileInput :size="26" /></span><h1>导入教案，开始分析</h1><p>上传已有教案，在这里编辑原文并与教学助手讨论。</p><div class="empty-actions"><label class="upload-button" for="lessonFile"><Upload :size="16" /> {{ busy ? '正在处理…' : '上传教案' }}</label><input id="lessonFile" class="file-input" type="file" accept=".docx,.txt,application/vnd.openxmlformats-officedocument.wordprocessingml.document,text/plain" :disabled="busy" aria-label="选择教案文件" @change="readText"><button :disabled="busy" @click="pasteOpen = !pasteOpen">{{ pasteOpen ? '收起粘贴区' : '粘贴教案' }}</button></div><p class="upload-hint">支持拖入 .docx 或 UTF-8 .txt，最大 5 MB。旧版 .doc 请先转换；Word 原有排版和图片不会保留。</p><p v-if="importedName" class="imported-file" role="status"><FileCheck2 :size="16" /> {{ importedName }} 已解析；请确认或重试保存。</p><div v-if="pasteOpen" class="paste-area"><label for="lessonText">教案正文</label><textarea id="lessonText" v-model="inputText" rows="10" maxlength="100000" :disabled="busy" aria-label="教案正文" placeholder="在这里粘贴完整教案……"></textarea><button class="primary" :disabled="busy || !inputText.trim()" @click="create">保存并开始分析 <ArrowRight :size="16" /></button></div></div></section>
      <LessonAssistant v-show="!assistantCollapsed || mobileSide" :ready="!!document" :workspace-id="workspaceId" :artifact-id="document?.id || ''" :version="document?.version || 0" :dirty="dirty" :saving="saving" :locked="!!document?.locked" :source-count="content?.selected_source_ids.length || 0" :selected-text="selectedText" :selection-key="selectionKey" @close="mobileSide = false" @sources="selectorOpen = true" @apply="applySuggestion" />
    </div>
    <div v-if="selectorOpen && content" class="backdrop" @click.self="selectorOpen = false" @keydown.esc="selectorOpen = false"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="source-title"><div class="section-head"><h2 id="source-title">选择授权教学资料</h2><button @click="selectorOpen = false" aria-label="关闭">×</button></div><p>选择已授权的教学资料；其他知识资源入口将在接入后开放。未选择资料也可使用通用分析。</p><div class="knowledge-slots" aria-label="待接入知识资源"><div v-for="slot in knowledgeSlots" :key="slot" class="knowledge-slot"><strong>{{ slot }}</strong><span>待接入</span></div></div><h3 class="source-heading">已授权资料</h3><input v-model="search" placeholder="搜索已授权资料" aria-label="搜索资料"><p v-if="!filteredSources.length" class="muted">{{ sources.length ? '没有匹配的授权资料。' : '暂无可用的授权资料。' }}</p><label v-for="source in filteredSources" :key="source.id" class="source"><input type="checkbox" :checked="content.selected_source_ids.includes(source.id)" :disabled="busy || document?.locked || (!content.selected_source_ids.includes(source.id) && content.selected_source_ids.length >= 20)" @change="toggleSource(source.id)"> {{ source.title }}</label><p v-for="id in unavailableSources" :key="id" class="alert">所选资料已不可用或权限已变更。<button @click="toggleSource(id)">移除</button></p><p>已选 {{ content.selected_source_ids.length }} 项</p><button class="primary" @click="selectorOpen = false">完成</button></section></div>
    <div v-if="versionsOpen && document" class="backdrop" @click.self="versionsOpen = false" @keydown.esc="versionsOpen = false"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="version-title"><div class="section-head"><h2 id="version-title">历史版本</h2><button @click="versionsOpen = false" aria-label="关闭">×</button></div><p>恢复会创建新版本；当前未保存修改需要先处理。</p><p v-if="!versions.length" class="muted">暂无版本。</p><div v-for="version in versions" :key="version.version" class="version"><div><strong>版本 {{ version.version }}</strong> · {{ version.created_at }}<details><summary>查看内容</summary><div v-for="section in version.content.sections" :key="section.id"><strong>{{ section.title }}</strong><p v-for="p in section.paragraphs" :key="p.id">{{ p.text }}</p></div></details></div><button :disabled="busy || dirty || document.locked || version.version === document.version" @click="restore(version.version)">恢复</button></div></section></div>
  </main>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import {ArrowRight, BookOpenCheck, Download, FileCheck2, FileInput, FileText, PanelLeft, PanelRight, Upload} from 'lucide-vue-next';
import LessonAssistant from './LessonAssistant.vue';
import { request, json, downloadLesson, type Artifact, type Source, type Workspace } from './api';

type Paragraph = { id: string; text: string };
type Section = { id: string; title: string; paragraphs: Paragraph[] };
type Content = { title: string; sections: Section[]; selected_source_ids: string[] };
type Version = { version: number; created_at: string; content: Content };
const props = defineProps<{initialWorkspace: Workspace | null; sources: Source[]}>();
const knowledgeSlots = ['课程标准', '教材与学科知识', '教学案例', '探究教学策略', '学段适配与学习支架', '校本资源'];
const emit = defineEmits<{close: []; exit: []}>();
const workspaceId = ref(props.initialWorkspace?.id || '');
const document = ref<Artifact | null>(props.initialWorkspace?.artifacts.find(a => a.type === 'LessonDocument') || null);
const copy = <T,>(value: T): T => JSON.parse(JSON.stringify(value)) as T;
const content = ref<Content | null>(document.value ? copy(document.value.content as unknown as Content) : null);
function fullText(value: Content): string { return value.sections.map(s => { const lines = s.paragraphs.map(p => p.text); if (s.title !== '教案原文' && lines[0]?.trim().replace(/[：:]$/, '') !== s.title) lines.unshift('## ' + s.title); return lines.join('\n'); }).join('\n'); }
const markdown = ref(content.value ? fullText(content.value) : '');
const baseline = ref(content.value ? JSON.stringify(content.value) : '');
const baselineMarkdown = ref(content.value ? content.value.sections.flatMap(s => s.paragraphs.map(p => p.text)).join('\n') : '');
const dirty = computed(() => content.value !== null && (JSON.stringify(content.value) !== baseline.value || markdown.value !== baselineMarkdown.value));
const markdownEditor = ref<HTMLTextAreaElement | null>(null), selectedText = ref(''), selectionStart = ref(0), selectionEnd = ref(0);
const selectionKey = computed(() => `${selectionStart.value}:${selectionEnd.value}:${selectedText.value}`);
const lastApplied = ref<{before:string;after:string} | null>(null);
function undoSuggestion() { if (lastApplied.value && markdown.value === lastApplied.value.after) { markdown.value = lastApplied.value.before; lastApplied.value = null; clearSelection(); } }
function captureSelection() { const el = markdownEditor.value; if (!el) return; selectionStart.value = el.selectionStart; selectionEnd.value = el.selectionEnd; selectedText.value = el.value.slice(el.selectionStart, el.selectionEnd); activeOutline.value = outlineItems.value.filter(item => item.offset <= el.selectionStart).at(-1)?.offset ?? -1; }
function clearSelection() { selectedText.value = ''; selectionStart.value = 0; selectionEnd.value = 0; }
function applySuggestion(text: string, selection: string, key: string) { const match = key.match(/^(\d+):(\d+):/); const start = match ? Number(match[1]) : -1, end = match ? Number(match[2]) : -1; if (!document.value || document.value.locked || dirty.value || busy.value || !selection || start < 0 || end < start || key.slice(match![0].length) !== selection || markdown.value.slice(start, end) !== selection) { error.value = '教案已锁定或原文已变化，无法采纳。'; return; } const before = markdown.value; markdown.value = before.slice(0, start) + text + before.slice(end); lastApplied.value = {before, after:markdown.value}; clearSelection(); void save(true); }
function contentForSave(value: Content): Content { if (markdown.value === baselineMarkdown.value) return copy(value); const previous = value.sections.flatMap(section => section.paragraphs); const lines = markdown.value.split('\n'); if (lines.length === previous.length && fullText(value) === baselineMarkdown.value) { const result = copy(value); let index = 0; for (const section of result.sections) for (const paragraph of section.paragraphs) paragraph.text = lines[index++]!; return result; } return {...copy(value), sections:[{id:value.sections[0]!.id,title:'教案原文',paragraphs:lines.map((text, index) => ({id:previous[index]?.text === text ? previous[index]!.id : 'para_' + crypto.randomUUID(),text}))}]}; }
function resetBaseline() { baseline.value = JSON.stringify(content.value); baselineMarkdown.value = content.value?.sections.flatMap(s => s.paragraphs.map(p => p.text)).join('\n') || ''; }

const importedName = ref(''), inputText = ref(''), error = ref(''), busy = ref(false), saving = ref(false), dragging = ref(false), pasteOpen = ref(false), current = ref(content.value?.sections[0]?.id || '');
const selectorOpen = ref(false), versionsOpen = ref(false), search = ref(''), mobileSide = ref(false), outlineCollapsed = ref(false), assistantCollapsed = ref(false), activeOutline = ref(-1);
const outlineItems = computed(() => { const items: {title:string;offset:number}[] = []; let offset = 0; for (const line of markdown.value.split('\n')) { const clean = line.trim(); const heading = clean.match(/^#{1,6}\s+(.+)/)?.[1] || (/^(教学背景|教学目标|教学重难点|教学重点与难点|教学准备|教学资源|教学过程|探究活动|学生任务|学习评价|教学反思)[：:]?$/.test(clean) ? clean.replace(/[：:]$/, '') : ''); if (heading) items.push({title:heading, offset}); offset += line.length + 1; } return items; });
function jumpToOutline(offset:number) { const el = markdownEditor.value; if (!el) return; activeOutline.value = offset; el.focus(); el.setSelectionRange(offset, offset); const lines = markdown.value.slice(0, offset).split('\n').length - 1; el.scrollTop = Math.max(0, lines * (parseFloat(getComputedStyle(el).lineHeight) || 27) - 40); captureSelection(); }
const versions = ref<Version[]>([]), undoStack = ref<Content[]>([]), redoStack = ref<Content[]>([]);
const filteredSources = computed(() => props.sources.filter(s => s.title.toLowerCase().includes(search.value.trim().toLowerCase())));
const unavailableSources = computed(() => content.value?.selected_source_ids.filter(id => !props.sources.some(s => s.id === id)) || []);
const path = () => `/api/inquiry-workspaces/${encodeURIComponent(workspaceId.value)}/lesson-document/${encodeURIComponent(document.value!.id)}`;
function message(e: unknown) { error.value = e instanceof Error ? e.message : '操作失败，请重试。'; }
function checkpoint() { if (!content.value) return; const last = undoStack.value.at(-1); if (!last || JSON.stringify(last) !== JSON.stringify(content.value)) { undoStack.value.push(copy(content.value)); if (undoStack.value.length > 100) undoStack.value.shift(); redoStack.value = []; } }
function undo() { if (!content.value || !undoStack.value.length) return; redoStack.value.push(copy(content.value)); content.value = undoStack.value.pop()!; }
function redo() { if (!content.value || !redoStack.value.length) return; undoStack.value.push(copy(content.value)); content.value = redoStack.value.pop()!; }
function jump(id: string) { current.value = id; globalThis.document.getElementById(id)?.scrollIntoView({behavior: 'smooth', block: 'start'}); }
function addSection() { if (!content.value || document.value?.locked || content.value.sections.length >= 100) return; checkpoint(); const id = 'sec_' + crypto.randomUUID(); content.value.sections.push({id, title:'新章节', paragraphs:[{id:'para_' + crypto.randomUUID(), text:''}]}); current.value = id; }
function deleteSection(id: string) { if (!content.value || content.value.sections.length <= 1 || !window.confirm('删除此章节及其正文？')) return; checkpoint(); content.value.sections = content.value.sections.filter(s => s.id !== id); current.value = content.value.sections[0]?.id || ''; }
function addParagraph(id: string) { if (!content.value || content.value.sections.reduce((n,s) => n + s.paragraphs.length, 0) >= 1000) { error.value = '最多支持 1000 个段落。'; return; } checkpoint(); content.value.sections.find(s => s.id === id)?.paragraphs.push({id:'para_' + crypto.randomUUID(), text:''}); }
function deleteParagraph(sectionId: string, paragraphId: string) { const section = content.value?.sections.find(s => s.id === sectionId); if (!section || section.paragraphs.length <= 1 || !window.confirm('删除这个段落？')) return; checkpoint(); section.paragraphs = section.paragraphs.filter(p => p.id !== paragraphId); }
function toggleSource(id: string) { if (!content.value || busy.value || document.value?.locked) return; checkpoint(); const ids = content.value.selected_source_ids; content.value.selected_source_ids = ids.includes(id) ? ids.filter(x => x !== id) : [...ids,id]; }
async function importFile(file: File) { if (busy.value) return; if (!/\.(txt|docx)$/i.test(file.name) || file.size > 5 * 1024 * 1024) { error.value = '请选择不超过 5 MB 的 TXT 或 DOCX 文件；旧版 DOC 请先转换。'; return; } if (inputText.value.trim() && !window.confirm('导入文件会替换当前正文，确定继续吗？')) return; let parsed = false; busy.value = true; error.value = ''; try { const form = new FormData(); form.append('file', file); const result = await request<{text:string}>('/api/inquiry-scenes/lesson-import', {method:'POST', body:form}); inputText.value = result.text; importedName.value = file.name; pasteOpen.value = true; parsed = true; } catch (e) { message(e); } finally { busy.value = false; } if (parsed) await create(); }
function readText(event: Event) { const input = event.target as HTMLInputElement, file = input.files?.[0]; input.value = ''; if (file) void importFile(file); }
function dropFile(event: DragEvent) { dragging.value = false; if (busy.value) return; const files = event.dataTransfer?.files; if (!files?.length) return; if (files.length !== 1) { error.value = '请一次导入一个教案文件。'; return; } void importFile(files[0]!); }
async function create() { if (busy.value || !inputText.value.trim()) return; const title = (importedName.value.replace(/\.(txt|docx)$/i, '').trim() || inputText.value.split(/\r?\n/).find(line => line.trim())?.trim() || '未命名教案').slice(0, 200); busy.value = true; error.value = ''; try { if (!workspaceId.value) { const workspace = await request<{id:string}>('/api/inquiry-workspaces', json('POST', {title})); workspaceId.value = workspace.id; } document.value = await request<Artifact>(`/api/inquiry-workspaces/${encodeURIComponent(workspaceId.value)}/lesson-document`, json('POST', {title,text:inputText.value})); content.value = copy(document.value.content as unknown as Content); markdown.value = fullText(content.value); resetBaseline(); current.value = content.value.sections[0]?.id || ''; } catch (e) { message(e); } finally { busy.value = false; } }
async function save(automatic = false) { if (!document.value || !content.value || busy.value) return; busy.value = true; saving.value = true; error.value = ''; try { const result = await request<Artifact>(path(), json('PUT', {expected_version:document.value.version,content:contentForSave(content.value)})); document.value = result; content.value = copy(result.content as unknown as Content); markdown.value = fullText(content.value); resetBaseline(); clearSelection(); } catch (e) { if (automatic) error.value = `自动保存失败，修改仍保留在正文中，请先复制正文备份。${e instanceof Error ? e.message : '请检查后重试。'}`; else message(e); } finally { saving.value = false; busy.value = false; } }
async function showVersions() { if (!document.value) return; try { versions.value = await request<Version[]>(`/api/inquiry-workspaces/${encodeURIComponent(workspaceId.value)}/artifacts/${encodeURIComponent(document.value.id)}/versions`); versionsOpen.value = true; } catch (e) { message(e); } }
async function restore(version: number) { if (!document.value || document.value.locked || dirty.value || !window.confirm('恢复这个版本并创建新版本？')) return; busy.value = true; try { const result = await request<Artifact>(`/api/inquiry-workspaces/${encodeURIComponent(workspaceId.value)}/artifacts/${encodeURIComponent(document.value.id)}/restore`, json('POST',{expected_version:document.value.version,version})); document.value = result; content.value = copy(result.content as unknown as Content); markdown.value = fullText(content.value); resetBaseline(); clearSelection(); lastApplied.value = null; undoStack.value = []; redoStack.value = []; current.value = content.value.sections[0]?.id || ''; versionsOpen.value = false; } catch (e) { message(e); } finally { busy.value = false; } }
async function exportWord() { if (!document.value || dirty.value) return; busy.value = true; try { await downloadLesson(workspaceId.value, document.value.id); } catch (e) { message(e); } finally { busy.value = false; } }
function leave(destination: 'home' | 'dialogue') { if ((dirty.value || (!document.value && !!inputText.value.trim())) && !window.confirm('当前内容尚未保存，确定离开吗？')) return; if (destination === 'dialogue') emit('exit'); else emit('close'); }
function beforeUnload(event: BeforeUnloadEvent) { if (dirty.value || (!document.value && inputText.value.trim())) { event.preventDefault(); event.returnValue = ''; } }
onMounted(() => window.addEventListener('beforeunload', beforeUnload));
onBeforeUnmount(() => window.removeEventListener('beforeunload', beforeUnload));
</script>
<style scoped>
.lesson{min-height:100%;background:var(--studio-bg);color:var(--studio-ink);font:15px/1.65 var(--studio-font)}.lesson *{box-sizing:border-box}.lesson button,.lesson input,.lesson textarea,.lesson select{font:inherit}.lesson button{display:inline-flex;align-items:center;justify-content:center;gap:6px;border:1px solid var(--studio-line);border-radius:var(--studio-control-radius);background:white;color:var(--studio-ink);padding:9px 13px;font-weight:650;cursor:pointer;transition:border-color .18s,background .18s}.lesson button:hover:not(:disabled){border-color:#8fc9a6;background:#f6faf7}.lesson button:disabled{opacity:.5;cursor:not-allowed}.lesson button:focus-visible,.lesson input:focus-visible,.lesson textarea:focus-visible,.lesson select:focus-visible{outline:3px solid #8fc9a6;outline-offset:2px}.lesson .primary{background:var(--studio-green);border-color:var(--studio-green);color:white}.lesson .primary:hover:not(:disabled){background:var(--studio-green-dark);color:white}
